function triggerFileDownload(file) {
	const url = URL.createObjectURL(file);
	const link = document.createElement("a");
	link.href = url;
	link.download = file.name;
	document.body.appendChild(link);
	link.click();
	document.body.removeChild(link);
	setTimeout(() => URL.revokeObjectURL(url), 5e3);
}
function fileToBase64(file) {
	return new Promise((resolve, reject) => {
		const reader = new FileReader();
		reader.onload = () => {
			const res = String(reader.result ?? "");
			const commaIdx = res.indexOf(",");
			resolve(commaIdx >= 0 ? res.slice(commaIdx + 1) : res);
		};
		reader.onerror = () => reject(reader.error);
		reader.readAsDataURL(file);
	});
}
async function sharePlainText(title, text) {
	if (Capacitor.isNativePlatform()) try {
		await Share.share({
			title,
			text,
			dialogTitle: "اشتراک‌گذاری پیش‌فاکتور"
		});
		return "shared";
	} catch {
		return "aborted";
	}
	if (typeof navigator !== "undefined" && navigator.share) try {
		await navigator.share({
			title,
			text
		});
		return "shared";
	} catch (err) {
		if (err?.name === "AbortError") return "aborted";
	}
	try {
		await navigator.clipboard.writeText(text);
		return "copied";
	} catch {
		return "failed";
	}
}
async function shareOrSavePdfFile(file) {
	if (Capacitor.isNativePlatform()) {
		const base64Data = await fileToBase64(file);
		const saved = await Filesystem.writeFile({
			path: `bannasanj-${Date.now()}.pdf`,
			data: base64Data,
			directory: Directory.Cache
		});
		try {
			await Share.share({
				title: "پیش‌فاکتور بناسنج",
				text: "فایل PDF برآورد مصالح و هزینه دیوارچینی",
				url: saved.uri,
				dialogTitle: "ذخیره یا ارسال فایل PDF"
			});
			return "shared";
		} catch {
			return "aborted";
		}
	}
	const navWithCanShare = navigator;
	if (typeof navigator !== "undefined" && navigator.share && navWithCanShare.canShare && navWithCanShare.canShare({ files: [file] })) try {
		await navigator.share({
			title: "پیش‌فاکتور بناسنج",
			text: "فایل PDF برآورد مصالح و هزینه دیوارچینی",
			files: [file]
		});
		return "shared";
	} catch (err) {
		if (err?.name === "AbortError") return "aborted";
	}
	triggerFileDownload(file);
	return "downloaded";
}
